using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: Default discriminator property renamed from
        // "Discriminator" to "$type" in EF Core 9. Restore the old name
        // so existing documents are still found.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2: Default id format changed from
        // "EntityType|Key" to just "Key". Restore the old format
        // so existing documents (e.g. "Blog|1") are still matched.
        modelBuilder.Entity<Blog>().HasPartitionKey(b => b.Id);
        modelBuilder.Entity<Blog>().Property(b => b.Id)
            .ToJsonProperty("id")
            .HasValueGenerator<LegacyCosmosIdGenerator>();

        // Breaking change 3: HasIndex now throws for Cosmos.
        // Removed the unsupported HasIndex call that was silently ignored in v8.
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; }

    // Value generator that preserves the EF Core 8 "Discriminator|Key" id format.
    class LegacyCosmosIdGenerator : Microsoft.EntityFrameworkCore.ValueGeneration.ValueGenerator<string>
    {
        public override bool GeneratesTemporaryValues => false;
        public override string Next(Microsoft.EntityFrameworkCore.ChangeTracking.EntityEntry entry)
            => $"{entry.Metadata.ShortName()}|{entry.Property("Id").CurrentValue}";
    }
}

